import java.io.IOException;
import java.util.*;

public class Test {
    int readInt() {
        int num = 0;
        boolean negative = false;
        try {
            boolean started = false;
            for (int ch = 0; (ch = System.in.read()) != -1; ) {
                if (ch == '-') {
                    started = true;
                    negative = true;
                    continue;
                } else if (ch >= '0' && ch <= '9') {
                    started = true;
                    num = num * 10 + ch - '0';
                } else if (started) break;
            }
        } catch (IOException e) {
        }
        return negative ? -num : num;
    }

    int rows, cols;
    Scanner scanner = new Scanner(System.in);
    long[][] binomial = new long[64][64];
    long minDiff = Long.MAX_VALUE;

    void explore(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (minDiff <= 1 || diff - binomial[v1][rows]*binomial[v2][rows] >= minDiff) return;
        if (v1 == rows - 1 && v2 == rows - 1) {
            if (diff < minDiff) minDiff = diff;
            return;
        }
        if (v1 >= rows) {
            long deltaX = binomial[v1][rows] - binomial[v1-1][rows], deltaY = binomial[v2][rows];
            explore(x, y + deltaX*deltaY, v1 - 1, v2);
        }
        if (v2 >= rows) {
            long deltaX = binomial[v1][rows], deltaY = binomial[v2][rows] - binomial[v2-1][rows];
            explore(x + deltaX*deltaY, y, v1, v2 - 1);
        }
    }

    int[] countA = new int[64], countB = new int[64];
    Map<Long, Long> cacheMap = new TreeMap<>();
    char[] sequence;

    long compute(long x, long y, int v1, int v2) {
        long key = x*10000 + v1*100 + v2;
        Long cached = cacheMap.get(key);
        if (cached != null) return cached;
        long res = 0L;
        long d = Math.abs(x - y);
        if (d - binomial[v1][rows]*binomial[v2][rows] > minDiff) {
            cacheMap.put(key, res);
            return res;
        }
        if (v1 < rows || v2 < rows) {
            int sumIdx = v1 + v2;
            if (v1 >= countA[sumIdx] && v2 >= countB[sumIdx]) {
                v1 -= countA[sumIdx];
                v2 -= countB[sumIdx];
                res = binomial[v1+v2][v1];
                cacheMap.put(key, res);
                return res;
            }
            cacheMap.put(key, res);
            return res;
        }
        char c = sequence[v1 + v2 - 1];
        if (c != 'B') {
            long c1 = binomial[v1][rows] - binomial[v1 - 1][rows], s2 = binomial[v2][rows];
            res += compute(x, y + c1*s2, v1 - 1, v2);
        }
        if (c != 'A') {
            long s1 = binomial[v1][rows], c2 = binomial[v2][rows] - binomial[v2-1][rows];
            res += compute( x + s1*c2, y, v1, v2 - 1);
        }
        cacheMap.put(key, res);
        return res;
    }

    void run() {
        rows = scanner.nextInt(); cols = scanner.nextInt(); scanner.nextLine();
        sequence = scanner.nextLine().toCharArray();
        for (int i = 0; i <= 2*(rows + cols); i++)
            for (int j = 0; j <= 2*(rows + cols); j++) {
                if (j == 0) binomial[i][j] = 1;
                else if (i == 0) binomial[i][j] = 0;
                else binomial[i][j] = binomial[i-1][j-1] + binomial[i-1][j];
            }
        int v1 = rows + cols, v2 = rows + cols;
        long xCoord = 0, yCoord = 0;
        while (v1 >= rows && v2 >= rows) {
            if (xCoord > yCoord) {
                long c1 = binomial[v1][rows] - binomial[v1 - 1][rows], s2 = binomial[v2][rows];
                yCoord += c1 * s2;
                v1--;
            } else {
                long s1 = binomial[v1][rows], c2 = binomial[v2][rows] - binomial[v2-1][rows];
                xCoord += s1 * c2;
                v2--;
            }
        }
        minDiff = Math.abs(xCoord - yCoord);
        explore(0, 0, rows + cols, rows + cols);
        for (int i = 0; i < 2*(rows+cols); i++) {
            countA[i + 1] = countA[i] + (sequence[i] == 'A' ? 1 : 0);
            countB[i + 1] = countB[i] + (sequence[i] == 'B' ? 1 : 0);
        }
        long answer = compute(0, 0, rows + cols, rows + cols);
        System.out.println(answer);
    }

    public static void main(String[] args) {
        new Test().run();
    }
}
